"""The PostgreSQL schema.

The SQLite schema leans on three things PostgreSQL does not have: `rowid`,
`AUTOINCREMENT` and FTS5. Each has a direct replacement:

* `rowid` / `AUTOINCREMENT` -> `GENERATED BY DEFAULT AS IDENTITY`. The queue's
  primary key is now named `id`, so every `cq.rowid` in the code becomes `cq.id`.
* FTS5 -> a `search_vector tsvector` column kept current by a trigger, with a
  GIN index. `setweight` ranks title above description above body (A/B/D)
  the bm25 weights expressed.

The text search configuration is `simple`, not `english`: the index is
multilingual — Kannada, Hindi, Tamil and English pages all live in it — and
English stemming applied to Kannada text does nothing useful while `simple`
keeps every token intact for all of them.
"""

from __future__ import annotations

__all__ = ["POSTGRES_SCHEMA_STATEMENTS", "SEARCH_CONFIG"]

#: The text search configuration used by the trigger and by search queries.
SEARCH_CONFIG = "simple"

POSTGRES_SCHEMA_STATEMENTS: tuple[str, ...] = (
    """
    CREATE TABLE IF NOT EXISTS sites (
        site_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
        domain TEXT UNIQUE NOT NULL,
        canonical_url TEXT,
        created_at TIMESTAMPTZ DEFAULT now()
    )
    """,
    # --- categories ---------------------------------------------------------
    # A page's category was free text, which meant nothing constrained it and the
    # chip's code lived only in Python. This is the one place a category is
    # defined; `pages.category_id` points at it.
    """
    CREATE TABLE IF NOT EXISTS categories (
        id SERIAL PRIMARY KEY,
        code VARCHAR(32) UNIQUE NOT NULL,
        -- The classifier's own key for the category, which is what pages.category
        -- already holds. Storing it here is what makes the two joinable.
        name VARCHAR(128) NOT NULL
    )
    """,
    """
    INSERT INTO categories (code, name) VALUES
        ('GOV', 'government'),
        ('TECH', 'tech_developer'),
        ('NEWS', 'news_media'),
        ('JOBS', 'jobs_careers'),
        ('FINANCE', 'business_finance'),
        ('PAY', 'payments'),
        ('EDU', 'education_exams'),
        ('HEALTH', 'health_medical'),
        ('AGRI', 'agriculture_rural'),
        ('LEGAL', 'legal_judiciary'),
        ('WEB', 'general_reference'),
        ('COMMERCE', 'commerce')
    ON CONFLICT (code) DO NOTHING
    """,
    """
    CREATE TABLE IF NOT EXISTS pages (
        page_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
        site_id BIGINT REFERENCES sites(site_id),
        url TEXT UNIQUE NOT NULL,
        title TEXT,
        description TEXT,
        body_text TEXT,
        quality_score DOUBLE PRECISION DEFAULT 1.0,
        digest TEXT,
        category TEXT DEFAULT 'general_reference',
        language TEXT DEFAULT 'en',
        indexed_at TIMESTAMPTZ DEFAULT now(),
        brand_name TEXT,
        clean_url TEXT,
        action_title TEXT,
        search_vector tsvector
    )
    """,
    """
    CREATE TABLE IF NOT EXISTS crawl_queue (
        id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
        url TEXT UNIQUE NOT NULL,
        domain TEXT NOT NULL,
        status TEXT DEFAULT 'pending',
        retry_count INTEGER DEFAULT 0,
        created_at TIMESTAMPTZ DEFAULT now(),
        processed_at TIMESTAMPTZ,
        last_error TEXT
    )
    """,
    # Keep search_vector in step with the row. A trigger rather than application
    # code: every write path would otherwise have to remember, and one that
    # forgets makes a page silently unfindable.
    """
    CREATE OR REPLACE FUNCTION pages_search_vector_update() RETURNS trigger AS $$
    BEGIN
        NEW.search_vector :=
            setweight(to_tsvector('simple', coalesce(NEW.title, '')), 'A') ||
            setweight(to_tsvector('simple', coalesce(NEW.description, '')), 'B') ||
            -- Body carries the lowest weight (D) on purpose: a page that
            -- repeats a keyword through its footer and navigation should not
            -- outrank one that has it in the title. A=1.0 against D=0.1.
            setweight(to_tsvector('simple', coalesce(NEW.body_text, '')), 'D');
        RETURN NEW;
    END
    $$ LANGUAGE plpgsql
    """,
    "DROP TRIGGER IF EXISTS pages_search_vector ON pages",
    """
    CREATE TRIGGER pages_search_vector
        BEFORE INSERT OR UPDATE OF title, description, body_text ON pages
        FOR EACH ROW EXECUTE FUNCTION pages_search_vector_update()
    """,
    # --- indexes -----------------------------------------------------------
    # ADD COLUMN IF NOT EXISTS so an existing database gets the column and the
    # constraint on startup, not just a fresh one.
    "ALTER TABLE pages ADD COLUMN IF NOT EXISTS category_id INTEGER REFERENCES categories(id)",
    # Keep category_id derived from the text column, so a page written by any
    # path — crawler, revalidation, a manual insert — is linked without the
    # caller having to remember. This is what stops the two drifting apart.
    """
    CREATE OR REPLACE FUNCTION pages_category_id_sync() RETURNS trigger AS $$
    BEGIN
        IF NEW.category IS NULL OR NEW.category = '' THEN
            NEW.category_id := (SELECT id FROM categories WHERE code = 'WEB');
            RETURN NEW;
        END IF;

        NEW.category_id := (SELECT id FROM categories WHERE name = NEW.category);

        -- A row carrying the code rather than the classifier key.
        IF NEW.category_id IS NULL THEN
            NEW.category_id := (SELECT id FROM categories WHERE code = upper(NEW.category));
        END IF;

        -- An unknown category still links to something, rather than leaving the
        -- row uncategorised for ever.
        IF NEW.category_id IS NULL THEN
            NEW.category_id := (SELECT id FROM categories WHERE code = 'WEB');
        END IF;

        RETURN NEW;
    END
    $$ LANGUAGE plpgsql
    """,
    "DROP TRIGGER IF EXISTS pages_category_id ON pages",
    """
    CREATE TRIGGER pages_category_id
        BEFORE INSERT OR UPDATE OF category ON pages
        FOR EACH ROW EXECUTE FUNCTION pages_category_id_sync()
    """,
    # Existing rows: derive the link from the text they already carry.
    "UPDATE pages SET category = category WHERE category_id IS NULL",
    "CREATE INDEX IF NOT EXISTS idx_pages_category_id ON pages(category_id)",
    # Filtered search orders by quality within a category; the composite
    # lets PostgreSQL walk the index instead of sorting the matches.
    "CREATE INDEX IF NOT EXISTS idx_pages_category_quality "
    "ON pages(category_id, quality_score DESC)",
    "CREATE INDEX IF NOT EXISTS idx_pages_search ON pages USING GIN (search_vector)",
    "CREATE INDEX IF NOT EXISTS idx_pages_site ON pages(site_id)",
    # Partial unique index: the database itself enforces SHA-256 deduplication
    # on body text, so two crawl workers racing on the same page cannot both
    # insert it.
    "CREATE UNIQUE INDEX IF NOT EXISTS idx_pages_digest ON pages(digest) "
    "WHERE digest IS NOT NULL AND digest <> ''",
    "CREATE INDEX IF NOT EXISTS idx_pages_indexed_at ON pages(indexed_at)",
    "CREATE INDEX IF NOT EXISTS idx_queue_status ON crawl_queue(status, id)",
    "CREATE INDEX IF NOT EXISTS idx_queue_domain ON crawl_queue(domain)",
    "CREATE INDEX IF NOT EXISTS idx_queue_processed ON crawl_queue(status, processed_at)",
)
